rt the program.</p><div class="grid"><div><label>Estimated monthly volume</label><input class="field req" name="estimatedMonthlyVolume" placeholder="12 cases / month"></div><div><label>Estimated monthly units</label><input class="field" name="estimatedMonthlyUnits" type="number" step=".01" min="0"></div><div><label>Estimated monthly revenue</label><input class="field" name="estimatedMonthlyRevenue" type="number" step=".01" min="0"></div><div><label>Order frequency</label><select class="field req" name="orderFrequency"><option value="">Choose…</option><option>Weekly</option><option>Biweekly</option><option>Monthly</option><option>Seasonal</option><option>As needed</option></select></div><div><label>Fulfillment preference</label><select class="field req" name="fulfillmentPreference"><option value="">Choose…</option><option>Delivery</option><option>Pickup</option><option>Distributor</option><option>Flexible</option></select></div><div><label>Desired start date</label><input class="field" name="desiredStartDate" type="date"></div><div><label>Current supplier</label><input class="field" name="currentSupplier"></div><div><label>Freezer capacity</label><input class="field" name="freezerCapacity"></div><div><label>Sample interest</label><select class="field" name="sampleInterest"><option value="">Choose…</option><option>Ready now</option><option>Interested</option><option>Needs internal approval</option><option>Not yet</option></select></div><div class="wide"><label>Package sizes</label><div class="checks"><label class="check"><input type="checkbox" name="packageSizes" value="Pint"> Pint</label><label class="check"><input type="checkbox" name="packageSizes" value="3L pan"> 3L pan</label><label class="check"><input type="checkbox" name="packageSizes" value="5L pan"> 5L pan</label><label class="check"><input type="checkbox" name="packageSizes" value="Case"> Case</label><label class="check"><input type="checkbox" name="packageSizes" value="Private label"> Private label</label>