venue:'estimated_monthly_revenue',orderFrequency:'order_frequency',fulfillmentPreference:'fulfillment_preference',desiredStartDate:'desired_start_date',currentSupplier:'current_supplier',freezerCapacity:'freezer_capacity',sampleInterest:'sample_interest',flavorsInterest:'flavors_interest',storageNotes:'storage_notes',painPoints:'pain_points',buyingProcess:'buying_process',pricingNotes:'pricing_notes',decisionTimeline:'decision_timeline',estimatedValue:'estimated_value',qualificationStatus:'qualification_status',notes:'notes',nextStep:'next_step'};Object.entries(map).forEach(([name,key])=>{const e=$(name);if(e&&l[key]!=null)e.value=l[key]});$('privateLabelInterest').value=Number(l.private_label_interest||0)?'1':'';if(l.next_followup_at)$('nextFollowupAt').value=String(l.next_followup_at).replace(' ','T').slice(0,16);(l.package_sizes||[]).forEach(v=>{const e=[...f.querySelectorAll('input[name="packageSizes"]')].find(x=>x.value===v);if(e)e.checked=true});progress()}async function load(){const r=await fetch('api/wholesale-acquisition.php'+(cfg.id?'?id='+encodeURIComponent(cfg.id):''),{headers:{Accept:'application/json'},cache:'no-store'}),d=await r.json();if(!r.ok||!d.ok){status.textContent=d.message||'Could not load worksheet.';return}(d.users||[]).forEach(u=>document.getElementById('assigned').insertAdjacentHTML('beforeend',`<option value="${u.id}">${String(u.display_name).replace(/[&<>]/g,'')}</option>`));fill(d.lead)}async function save(action){try{status.textContent='Saving…';const d=await api(payload(action));cfg.id=d.lead.public_id;$('id').value=cfg.id;history.replaceState({},'',`wholesale-acquisition.php?id=${encodeURIComponent(cfg.id)}`);status.textContent=d.message+' Lead '+cfg.id;fill(d.lead)}catch(e){status.textContent=e.message}}f.addEventListener('input',progress);f.addEventListener('change',progress);document.getElementById('save').onclick=()=>save('save');document.getElementById('complete').onclick=()=>save('complete');progress();load()})();</script></body></html>
